/// signal Button.clicked: GtkButton::clicked is an action signal with void return (Gtk 4 docs)
#[test]
fn signal_button_clicked() {
    on_gtk(|| {
        let mut h = Harness::new();
        let e = h.create("button");
        let o = e;
        
        let fire = |o: &gtk::glib::Object, v: &str, i: usize| {
            let _ = (v, i);
            let _ = v; o.emit_by_name::<()>("clicked", &[]);
        };
        assert_ne!(h.resolve_signal("button", "clicked"), 0);
        assert_eq!(h.resolve_signal("button", "clicked"), h.resolve_signal("button", "clicked"));
        h.listen(e, "clicked", true).unwrap();
        fire(&h.obj(e), "a", 0);
        // GTK may emit a signal several times per edit (e.g. delete + insert for set_text).
        let ev = h.take_events();
        assert!(!ev.is_empty() && ev.iter().all(|x| *x == (e, "clicked".to_string())), "delivered: {ev:?}");
        h.listen(e, "clicked", false).unwrap();
        fire(&h.obj(e), "b", 1);
        assert!(h.take_events().is_empty(), "no delivery after listen(off)");
        h.listen(e, "clicked", true).unwrap();
        let obj = h.obj(e);
        h.destroy(e);
        fire(&obj, "c", 2);
        assert!(h.take_events().is_empty(), "handler is disconnected on destroy");
        assert!(h.listen(e, "clicked", true).is_err(), "stale handle is an error");
    });
}

